css:
.pl { font-size: 11px; } .pl h3 { text-align:center; margin:0 } .pl .sub { text-align:center; margin:2px 0 10px }
.pl table { width:100%; border-collapse:collapse } .pl td, .pl th { border:1px solid #666; padding:3px 7px }
.pl .num { text-align:right } .pl .lbl { width:62% } .pl .sec td { background:#f0f0f0; font-weight:bold }
.pl .net td { font-weight:bold; background:#eef; font-size:12px } .pl .muted td { color:#555 }
.pl .sign { border:0; text-align:center; width:50%; padding-top:34px } .pl .note { font-size:9px; color:#555; margin-top:8px }

html:
{%- macro m(v) -%}{{ frappe.format(v or 0, {"fieldtype":"Currency","options":"currency"}) }}{%- endmacro -%}
{%- set c = {} -%}{%- for r in doc.earnings + doc.deductions -%}{%- set _ = c.update({r.salary_component: r.amount}) -%}{%- endfor -%}
{%- macro line(label, comp) -%}<tr><td>{{ label }}</td><td class="num">{{ m(c.get(comp)) }}</td></tr>{%- endmacro -%}
<div class="pl">
	<h3>PHIẾU LƯƠNG</h3>
	<p class="sub">{{ doc.employee }} &mdash; {{ doc.employee_name }}<br>
		Kỳ lương: {{ frappe.format(doc.start_date,{"fieldtype":"Date"}) }} &ndash; {{ frappe.format(doc.end_date,{"fieldtype":"Date"}) }}</p>
	<table>
		<tr class="sec"><td class="lbl">Thông số</td><td class="num">Giá trị</td></tr>
		<tr><td>Loại lương</td><td class="num">{{ doc.custom_salary_type or "" }}</td></tr>
		<tr><td>Hệ số lương (E)</td><td class="num">{{ doc.custom_coefficient or 1 }}</td></tr>
		<tr><td>Số người phụ thuộc (M)</td><td class="num">{{ doc.custom_dependents_slip or 0 }}</td></tr>
		<tr><td>Công chuẩn / thực tế (H)</td><td class="num">{{ doc.total_working_days }} / {{ doc.payment_days }}</td></tr>
		<tr><td>Số ngày ăn trưa</td><td class="num">{{ doc.custom_lunch_days or 0 }}</td></tr>

		<tr class="sec"><td>Thu nhập</td><td class="num"></td></tr>
		{{ line("Lương ngày công (F)", "Lương ngày công") }}
		{{ line("Lương đóng BHXH (G)", "Lương đóng BHXH") }}
		{{ line("Lương theo công (I)", "Lương theo công") }}
		{{ line("Phụ cấp ăn trưa (J) — miễn thuế", "Phụ cấp ăn trưa") }}
		{{ line("Tiền thưởng", "Tiền thưởng") }}
		<tr><td><b>Tổng thu nhập (K)</b></td><td class="num"><b>{{ m(c.get("Tổng thu nhập")) }}</b></td></tr>

		<tr class="sec"><td>Giảm trừ gia cảnh</td><td class="num"></td></tr>
		{{ line("Giảm trừ bản thân (L)", "Giảm trừ bản thân") }}
		{{ line("Tổng giảm trừ (N)", "Tổng giảm trừ gia cảnh") }}

		<tr class="sec"><td>Thuế thu nhập cá nhân</td><td class="num"></td></tr>
		{{ line("Thu nhập quy đổi (O)", "Thu nhập quy đổi") }}
		{{ line("Thu nhập tính thuế (P)", "Thu nhập tính thuế") }}
		{{ line("Thuế TNCN (Q) — công ty nộp thay", "Thuế TNCN (nộp thay)") }}

		<tr class="sec"><td>Bảo hiểm bắt buộc</td><td class="num"></td></tr>
		{{ line("BHXH - Công ty trả (R)", "BHXH - Công ty") }}
		{{ line("BHXH - NLĐ (S) — công ty nộp thay", "BHXH - NLĐ (nộp thay)") }}

		<tr class="net"><td>THỰC LĨNH (T)</td><td class="num">{{ m(doc.net_pay) }}</td></tr>
		{{ line("Thu nhập chịu thuế kê khai (U)", "Thu nhập chịu thuế kê khai") }}
	</table>
	<p class="note">Lương NET: người lao động nhận đúng THỰC LĨNH (T = I + J); thuế TNCN (Q) và BHXH phần NLĐ (S) do công ty nộp thay, KHÔNG trừ vào thực lĩnh. Tổng chi phí công ty = T + Q + S + R.</p>
	<table style="margin-top:14px;border:0">
		<tr><td class="sign">NGƯỜI LẬP<br><i>(Ký, ghi rõ họ tên)</i></td><td class="sign">NGƯỜI NHẬN<br><i>(Ký, ghi rõ họ tên)</i></td></tr>
	</table>
</div>
